use WexaShelf\{Database,Repository,CatalogQuery,Translations};
if($argc!==2)throw new RuntimeException('Usage: php php/tests/catalog-query.php QA_DATABASE_JSON');
$config=json_decode(file_get_contents($argv[1]),true,512,JSON_THROW_ON_ERROR);if(!isset($config['database']))$config=['database'=>$config];$config['database']['name']='wexashelf_catalog_070';$db=Database::connect($config);Database::migrate($db);$repo=new Repository($db,$config);$index=new CatalogQuery($db,$repo);
