$db->beginTransaction();try{
 $seed=json_decode(file_get_contents(__DIR__.'/../resources/seed.json'),true,512,JSON_THROW_ON_ERROR);$repo->seed($seed);$source=$repo->record('app','notion');if(!$source)throw new RuntimeException('Expected seed app');
 for($i=0;$i<61;$i++){$r=$source;$r['id']=$r['data']['id']='catalog-test-'.str_pad((string)$i,3,'0',STR_PAD_LEFT);$r['sourceLocale']='en';$r['revision']=0;$r['data']['name']='Findable application '.$i;$r['data']['aliases']=['uniquealias'];$r['data']['tags']=['Review tag'];$r['data']['platforms']=$i%2?['ios']:['android','windows'];$r['data']['plans']=[];$r['data']['facts']=[];$r['data']['storeMetrics']=[];$r['data']['storeIds']=[];$r['data']['storeLinks']=[];$r['data']['pricingModel']=$i%2?'unknown':'free';$r['admissionException']='Synthetic catalog test fixture';$repo->saveRecord($r);}
 $tagMatches=$index->search(['tag'=>'open-source'],'en');catalogAssert($tagMatches['total']>0,'localized English tag slug finds stored Turkish tag IDs');catalogAssert($tagMatches===$index->search(['tag'=>'open source'],'en')&&$tagMatches===$index->search(['tag'=>'açık kaynak'],'en'),'tag label, localized slug and stable ID select identical records');catalogAssert($index->search(['tag'=>'acik-kaynak'],'tr')['total']>0,'Turkish localized tag slug matches stable ID');
 $sourceCategory=$source['data']['category'];$categoryLabel='';foreach(\WexaShelf\Localization::content('tr')['categories']as$category)if($category['id']===$sourceCategory)$categoryLabel=$category['label'];catalogAssert($categoryLabel!==''&&$index->search(['q'=>$categoryLabel],'tr')['total']>0,'localized category labels remain searchable');
 $page=$index->search(['q'=>'uniquealias'],'en');catalogAssert($page['total']===61&&count($page['items'])===24&&$page['pages']===3,'bounded first page/count');$page2=$index->search(['q'=>'uniquealias','page'=>2],'en');catalogAssert(!array_intersect(array_column($page['items'],'id'),array_column($page2['items'],'id')),'stable nonoverlapping pages');
 catalogAssert($index->search(['q'=>'uniquealias','platform'=>'android,windows','mode'=>'all'],'en')['total']===31,'platform all');catalogAssert($index->search(['q'=>'uniquealias','exclude'=>'subscription'],'en')['total']===31,'unknown excluded from negative pricing');catalogAssert($index->search(['q'=>'uniquealias','tag'=>'review tag'],'en')['total']===61,'case normalized tags');catalogAssert($index->search(['q'=>'%'],'en')['total']===0,'SQL wildcards are literal');catalogAssert($index->search(['q'=>'uniquealias'],'tr')['total']===0,'source English does not leak into Turkish');
 $r=$repo->record('app','catalog-test-000');$r['status']='draft';$repo->saveRecord($r);catalogAssert($index->search(['ids'=>'catalog-test-000'],'en')['total']===0,'unpublish immediately removes projection');$r=$repo->record('app','catalog-test-001');$r['status']='scheduled';$r['publishAt']=gmdate('c',time()+3600);$repo->saveRecord($r);catalogAssert($index->search(['ids'=>'catalog-test-001'],'en')['total']===0,'future scheduled hidden');
 $catalog=$repo->getPublicSnapshot($page2['items']);catalogAssert(count($catalog['apps'])===24&&count($catalog['records'])===24,'selected snapshot does not load entire catalog');
